recipe:
let
  root = /home/dylan/src/aos/.worktrees/codex/bazel-integration-722;
  pkgs = (import root {}).pkgs;
  source = root + "/crates/aos/boot/aos-boot-runtime/standalone";
in pkgs.mkDerivation {
  pname = "aos-bazel-boot-preparation-standalone-rustc-baseline";
  version = "1";
  src = source;
  buildDeps = [pkgs.rust];
  runtimeDeps = [pkgs.aos.packageRuntime pkgs.aos-configuration-lower];
  sharedBuildCache = false;
  dontStrip = true;
  dontPatchELF = true;
  dontNukeRefs = true;
  phases = [{
    name = "compile-and-test";
    script = ''
      mkdir -p "$out"
      export AOS_PACKAGE_RUNTIME=${pkgs.aos.packageRuntime}/bin/aos-package-runtime
      export AOS_BOOT_CONFIGURATION=${pkgs.aos.packageRuntime}/bin/aos-boot-configuration
      export AOS_CONFIGURATION_BOOT=${pkgs.aos-configuration-lower}/bin/aos-configuration-boot
      rustc --edition=2024 --crate-name aos_initrd_preparation "$src/initrd_preparation.rs" -o "$out/aos-boot-preparations"
      rustc --edition=2024 --crate-name aos_initrd_preparation --test "$src/initrd_preparation.rs" -o "$out/tests"
      "$out/tests" > "$out/tests.log"
      "$out/tests" --list > "$out/test-inventory.txt"
    '';
  }];
}
